import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Fused subtract + HardSwish kernel
__global__ void fused_sub_hardswish_kernel(const float* x,
                                           float* out,
                                           int size,
                                           float subtract_value) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx] - subtract_value;
        // HardSwish: x * ReLU6(x+3) / 6
        float relu6_val = fmaxf(0.0f, fminf(val + 3.0f, 6.0f));
        out[idx] = val * (relu6_val / 6.0f);
    }
}

torch::Tensor fused_sub_hardswish_cuda(torch::Tensor x, float subtract_value) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    fused_sub_hardswish_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        subtract_value
    );
    return out;
}

// Mish kernel
__global__ void mish_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // Mish: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
        float sp = expf(val);
        float softplus = logf(1.0f + sp);
        out[idx] = val * tanhf(softplus);
    }
}

torch::Tensor mish_cuda(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    mish_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );
    return out;
}
"""

fused_ops_cpp_source = r"""
torch::Tensor fused_sub_hardswish_cuda(torch::Tensor x, float subtract_value);
torch::Tensor mish_cuda(torch::Tensor x);
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_sub_hardswish_cuda", "mish_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, subtract_value, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.subtract_value = subtract_value
        self.pool = nn.MaxPool2d(pool_kernel_size)

    def forward(self, x):
        x = self.conv(x)
        x = fused_ops.fused_sub_hardswish_cuda(x, self.subtract_value)
        x = self.pool(x)
        x = fused_ops.mish_cuda(x)
        return x
